#include "semantic.h"
#include "diag.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Symbol {char *name;char *type;int is_function;SrcLoc loc;struct Symbol*next;} Symbol;
typedef struct Scope {struct Scope*parent;Symbol*symbols;} Scope;
static const char *active_return_type = NULL;
static Scope *scope_new(Scope*p){Scope*s=calloc(1,sizeof*s);if(!s){fputs("out of memory\n",stderr);exit(2);}s->parent=p;return s;}
static void scope_free(Scope*s){if(!s)return;Symbol*x=s->symbols;while(x){Symbol*n=x->next;free(x->name);free(x->type);free(x);x=n;}free(s);}
static Symbol*lookup(Scope*s,const char*n){for(;s;s=s->parent)for(Symbol*x=s->symbols;x;x=x->next)if(!strcmp(x->name,n))return x;return NULL;}
static Symbol*declare(Scope*s,const char*n,const char*t,int fn,SrcLoc loc){for(Symbol*x=s->symbols;x;x=x->next)if(!strcmp(x->name,n)){diag_add("SEM001",SEV_ERROR,loc,n,"Redeclaration of '%s' in the same scope",n);return x;}Symbol*x=calloc(1,sizeof*x);if(!x){fputs("out of memory\n",stderr);exit(2);}x->name=strdup(n);x->type=strdup(t?t:"int");x->is_function=fn;x->loc=loc;x->next=s->symbols;s->symbols=x;return x;}
static const char*type_of(const AstNode*n){return n&&n->text?n->text:"int";}
static int numeric(const char*t){return t&&(!strcmp(t,"int")||!strcmp(t,"float")||!strcmp(t,"double")||!strcmp(t,"char"));}
static const char*promote(const char*a,const char*b){if(!strcmp(a,"double")||!strcmp(b,"double"))return "double";if(!strcmp(a,"float")||!strcmp(b,"float"))return "float";return "int";}
static const char*expr_type(const AstNode*n,Scope*s);
static void visit_stmt(const AstNode*n,Scope*s);
static void visit_decl(const AstNode*n,Scope*s){const char*t=type_of(n);for(const AstNode*d=n->child;d;d=d->next){if(d->kind!=AST_DECLARATOR||!d->text)continue;declare(s,d->text,t,0,d->loc);if(d->child){const char*init=expr_type(d->child,s);if(numeric(t)&&numeric(init)&&strcmp(t,init)&&strcmp(t,"double")==0){}else if(!numeric(t)||!numeric(init))diag_add("SEM004",SEV_WARNING,d->loc,d->text,"Cannot fully verify initializer type for '%s' (%s <- %s)",d->text,t,init);}}}
static const char*expr_type(const AstNode*n,Scope*s){if(!n)return "void";switch(n->kind){case AST_LITERAL:if(n->text&&n->text[0]=='"')return "char*";if(n->text&&n->text[0]=='\'')return "char";if(n->text&&strchr(n->text,'.'))return "double";return "int";case AST_IDENTIFIER:{Symbol*x=lookup(s,n->text?n->text:"");if(!x){diag_add("SEM002",SEV_ERROR,n->loc,n->text,"Use of undeclared identifier '%s'",n->text?n->text:"");return "int";}if(x->is_function){diag_add("SEM005",SEV_ERROR,n->loc,n->text,"Function '%s' used without a call",n->text);return x->type;}return x->type;}case AST_ASSIGNMENT:{const AstNode*l=n->child,*r=l?l->next:NULL;const char*lt=expr_type(l,s),*rt=expr_type(r,s);if(l&&l->kind!=AST_IDENTIFIER&&l->kind!=AST_INDEX)diag_add("SEM006",SEV_ERROR,l->loc,l->text,"Left side of assignment is not assignable");if(numeric(lt)&&numeric(rt))return lt;if(strcmp(lt,rt))diag_add("SEM004",SEV_WARNING,n->loc,n->text,"Assignment mixes incompatible types '%s' and '%s'",lt,rt);return lt;}case AST_BINARY:{const AstNode*l=n->child,*r=l?l->next:NULL;const char*lt=expr_type(l,s),*rt=expr_type(r,s);if(n->text&&(!strcmp(n->text,"==")||!strcmp(n->text,"!=")||!strcmp(n->text,"<")||!strcmp(n->text,">")||!strcmp(n->text,"<=")||!strcmp(n->text,">=")||!strcmp(n->text,"&&")||!strcmp(n->text,"||")))return "int";if(!numeric(lt)||!numeric(rt)){diag_add("SEM004",SEV_WARNING,n->loc,n->text,"Operator '%s' applied to types '%s' and '%s'",n->text?n->text:"?",lt,rt);return "int";}return promote(lt,rt);}case AST_UNARY:return expr_type(n->child,s);case AST_CALL:{const AstNode*callee=n->child;Symbol*x=callee&&callee->kind==AST_IDENTIFIER?lookup(s,callee->text):NULL;if(!x)diag_add("SEM003",SEV_WARNING,n->loc,callee?callee->text:NULL,"External function '%s' has no visible declaration; call type cannot be verified",callee&&callee->text?callee->text:"");else if(!x->is_function)diag_add("SEM007",SEV_ERROR,n->loc,callee->text,"'%s' is not a function",callee->text);for(const AstNode*a=callee?callee->next:NULL;a;a=a->next)(void)expr_type(a,s);return x?x->type:"int";}case AST_INDEX:(void)expr_type(n->child,s);return "int";case AST_CONDITIONAL:{const AstNode*c=n->child,*a=c?c->next:NULL,*b=a?a->next:NULL;(void)expr_type(c,s);return promote(expr_type(a,s),expr_type(b,s));}default:for(const AstNode*c=n->child;c;c=c->next)(void)expr_type(c,s);return "int";}}
static void visit_stmt(const AstNode*n,Scope*s){if(!n)return;switch(n->kind){case AST_DECLARATION:visit_decl(n,s);break;case AST_BLOCK:{Scope*inner=scope_new(s);for(const AstNode*c=n->child;c;c=c->next)visit_stmt(c,inner);scope_free(inner);break;}case AST_FUNCTION:{const char*previous_return=active_return_type;active_return_type=n->type_name?n->type_name:"int";Scope*fn=scope_new(s);for(const AstNode*c=n->child;c;c=c->next){if(c->kind==AST_PARAMETER_LIST){for(const AstNode*p=c->child;p;p=p->next)if(p->kind==AST_PARAMETER&&p->text)declare(fn,p->text,p->type_name?p->type_name:"int",0,p->loc);}else if(c->kind==AST_BLOCK)visit_stmt(c,fn);}scope_free(fn);active_return_type=previous_return;break;}case AST_IF:case AST_WHILE:case AST_DO_WHILE:case AST_FOR:{for(const AstNode*c=n->child;c;c=c->next){if(c->kind==AST_DECLARATION)visit_decl(c,s);else if(c->kind==AST_BLOCK||c->kind==AST_IF||c->kind==AST_WHILE||c->kind==AST_DO_WHILE||c->kind==AST_FOR||c->kind==AST_RETURN||c->kind==AST_BREAK||c->kind==AST_CONTINUE||c->kind==AST_EXPRESSION_STATEMENT)visit_stmt(c,s);else (void)expr_type(c,s);}break;}case AST_RETURN:{const char*expected=active_return_type?active_return_type:"int";if(!n->child){if(strcmp(expected,"void"))diag_add("SEM008",SEV_ERROR,n->loc,NULL,"Non-void function should return a value of type '%s'",expected);}else{const char*actual=expr_type(n->child,s);if(!strcmp(expected,"void"))diag_add("SEM008",SEV_ERROR,n->loc,NULL,"Void function must not return a value");else if(!numeric(expected)||!numeric(actual)){if(strcmp(expected,actual))diag_add("SEM008",SEV_ERROR,n->loc,NULL,"Return type '%s' is incompatible with function return type '%s'",actual,expected);}}break;}case AST_EXPRESSION_STATEMENT:if(n->child)(void)expr_type(n->child,s);break;case AST_BREAK:case AST_CONTINUE:break;default:(void)expr_type(n,s);break;}}
int semantic_analyze(const AstNode*root){Scope*global=scope_new(NULL);const AstNode*n;for(n=root?root->child:NULL;n;n=n->next)if(n->kind==AST_FUNCTION)declare(global,n->text?n->text:"<anonymous>",n->type_name?n->type_name:"int",1,n->loc);for(n=root?root->child:NULL;n;n=n->next)if(n->kind==AST_DECLARATION)visit_decl(n,global);for(n=root?root->child:NULL;n;n=n->next)if(n->kind==AST_FUNCTION)visit_stmt(n,global);scope_free(global);return diag_error_count();}
